inputs = ['ek', 'kbivwy', 'hfxwvi', 'kykxk', 'cbw']
outputs = ['exxu', 'xxudidivwfud', 'jyjfxwvi', 'xxufudxxuxxxu', 'cdidw']

# Let's manually trace each transformation
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Example {i+1}: '{inp}' → '{outp}'")

    # Show positions where chars differ
    min_len = min(len(inp), len(outp))
    diffs = []
    for j in range(min_len):
        if inp[j] != outp[j]:
            diffs.append((j, inp[j], outp[j]))

    if len(outp) > len(inp):
        for j in range(len(inp), len(outp)):
            diffs.append((j, '_', outp[j]))  # Added char
    elif len(inp) > len(outp):
        for j in range(len(outp), len(inp)):
            diffs.append((j, inp[j], '_'))  # Removed char

    if diffs:
        print(f"  Differences at positions: {diffs}")
    else:
        print("  No character differences")
    print()

